using System.Text.Json;using System.Text.Json.Nodes;using System.Reflection;
namespace RisingLands;
public static class SharedVisionTests {
 public static void Run(string root,string output){int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}var s=BaseDefenseTests.Load(root,5,3);
  var own=s.World.Units.First(a=>a.Owner==0&&a.Type==0&&VisualCatalog.Visible(a));var ally=s.World.Units.First(a=>a.Owner==1&&a.Type==0&&VisualCatalog.Visible(a));var enemy=s.World.Units.First(a=>a.Owner==2&&a.Type==0&&VisualCatalog.Visible(a));
  int Far(){var views=Enumerable.Range(1,3).Select(s.EnemyCurrentVisionForResearch).ToArray();return Enumerable.Range(0,65536).First(c=>(c&255)<s.World.Width&&(c>>8)<s.World.Height&&s.World.Objects[c]==0&&s.Passable(c&255,c>>8)&&!s.InSight(c)&&views.All(v=>v[c]==0));}
  int far=Far();ally.X=(far&255)*1024;ally.Y=(far>>8)*1024;enemy.X=ally.X+1024;enemy.Y=ally.Y;s.UpdateVisibility();Check(!s.InSight(far)&&!s.UnitInSight(enemy),"enemy activity hidden without alliance");s.Campaign.Alliances[1]=true;s.UpdateVisibility();Check(s.InSight(far)&&s.Discovered(far)&&s.UnitInSight(enemy),"allied troop reveals territory and nearby enemy");Check(s.EnemyCurrentVisionForResearch(1)[own.Y/1024*256+own.X/1024]!=0,"player vision shared reciprocally");
  Check(!s.Opponent.KnownUnits[3].TryGetValue(enemy.Slot,out var rememberedEnemy)||rememberedEnemy.Cell!=enemy.Y/1024*256+enemy.X/1024,"unallied clan does not receive another clan observations");var third=s.World.Units.First(a=>a.Owner==3&&a.Type==0&&VisualCatalog.Visible(a));int thirdCell=Far();third.X=(thirdCell&255)*1024;third.Y=(thirdCell>>8)*1024;s.Campaign.Alliances[3]=true;s.UpdateVisibility();Check(s.InSight(thirdCell)&&s.EnemyCurrentVisionForResearch(1)[thirdCell]==0,"shared vision is direct and does not relay hostile third clan");s.Campaign.Alliances[3]=false;s.UpdateVisibility();var home=s.World.Buildings.First(b=>b.Owner==1&&b.Type==2);Check(s.BuildingInSight(home)&&s.Exploration.Structures.ContainsKey(home.Slot),"allied construction reveals and records structure");s.Campaign.Alliances[1]=false;s.UpdateVisibility();Check(!s.InSight(far)&&s.Discovered(far)&&!s.UnitInSight(enemy),"break stops live vision but preserves exploration");Check(!s.BuildingInSight(home)&&s.Exploration.Structures.ContainsKey(home.Slot),"last observed building retained after break");
  int oldHealth=s.Exploration.Structures[home.Slot].Health;typeof(Simulation).GetMethod("HitStructure",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(s,new object[]{home,s.BuildingMaxHealth(home),2});s.UpdateVisibility();Check(!s.World.Buildings.Contains(home)&&s.Exploration.Structures[home.Slot].Health==oldHealth,"hidden destruction does not alter remembered building");
  s.Campaign.Alliances[1]=true;s.UpdateVisibility();Check(!s.Exploration.Structures.ContainsKey(home.Slot),"reobserving empty footprint removes stale building");s.Campaign.Alliances[1]=false;s.UpdateVisibility();
  foreach(int owner in Enumerable.Range(1,3)){var known=s.Opponent.Explored[owner];Check(known.Count(v=>v!=0)==s.World.Width*s.World.Height,"clan knows all terrain "+owner);Check(s.EnemyCurrentVisionForResearch(owner).Count(v=>v!=0)<s.World.Width*s.World.Height,"terrain knowledge does not reveal all cells "+owner);int resource=Enumerable.Range(0,65536).First(c=>s.World.Objects[c] is >=29 and <=52 or 66 or 67 or 68);Check(s.Opponent.KnownResources[owner][resource]!=0,"initial resource location known "+owner);}
  int hidden=Far();var unknown=new Building(6300,3,0,hidden);s.World.Buildings.Add(unknown);s.UpdateVisibility();s.EnemyCurrentVisionForResearch(3);Check(!s.Opponent.KnownStructures[3].ContainsKey(unknown.Slot),"full terrain never reveals new hidden player building");s.World.Buildings.Remove(unknown);s.World.Objects[hidden]=67;s.World.Quantities[hidden]=5;s.UpdateVisibility();s.EnemyCurrentVisionForResearch(3);Check(s.Opponent.KnownResources[3][hidden]==0,"new hidden resource pile not revealed by terrain knowledge");s.World.Objects[hidden]=0;s.World.Quantities[hidden]=0;
  int hiddenUnit=Far();own.X=(hiddenUnit&255)*1024;own.Y=(hiddenUnit>>8)*1024;s.UpdateVisibility();ally.AttackTarget=own.Slot;typeof(Simulation).GetMethod("CombatStep",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(s,null);Check(ally.AttackTarget<0,"enemy stops tracking exact position after target leaves all allied sight");
  var natural=BaseDefenseTests.Load(root);natural.Campaign.Alliances[1]=true;natural.UpdateVisibility();for(int i=0;i<60;i++)natural.Step();string json=natural.Serialize();var copy=BaseDefenseTests.Load(root);copy.Restore(json);Check(copy.Serialize()==json,"active alliance and memory save exactly");for(int i=0;i<60;i++){natural.Step();copy.Step();}Check(copy.Serialize()==natural.Serialize(),"shared visibility continuation deterministic");natural.Campaign.Alliances[1]=false;natural.UpdateVisibility();json=natural.Serialize();copy.Restore(json);Check(copy.Serialize()==json&&!copy.Allied(1),"broken alliance and retained memory survive save");
  var legacy=JsonNode.Parse(json)!;legacy["Version"]=40;legacy["Exploration"]!.AsObject().Remove("Structures");foreach(string key in new[]{"KnownStructures","KnownResources","KnownUnits"})legacy["Opponent"]!.AsObject().Remove(key);var migrated=BaseDefenseTests.Load(root);migrated.Restore(legacy.ToJsonString());Check(migrated.Opponent.Explored[1].Count(v=>v!=0)==migrated.World.Width*migrated.World.Height,"old save receives full terrain without troop revelation");var bad=JsonNode.Parse(json)!;bad["Opponent"]!["KnownResources"]!["1"]=Convert.ToBase64String(new byte[3]);string prior=copy.Serialize();try{copy.Restore(bad.ToJsonString());throw new Exception("Malformed knowledge accepted");}catch(InvalidDataException){}Check(copy.Serialize()==prior,"invalid knowledge rejected atomically");
  var breach=BaseDefenseTests.Load(root);var attacker=breach.World.Units.First(a=>a.Owner==0&&a.Type==0&&VisualCatalog.Visible(a));var victim=breach.World.Units.First(a=>a.Owner==1&&a.Type==0&&VisualCatalog.Visible(a));var alliedHome=breach.World.Buildings.First(b=>b.Owner==1&&b.Type==2);breach.Campaign.Alliances[1]=true;breach.UpdateVisibility();Check(breach.BuildingInSight(alliedHome),"alliance reveals distant building before attack");Check(breach.Attack(attacker,victim)&&!breach.Allied(1)&&!breach.BuildingInSight(alliedHome),"attacking ally ends shared vision immediately through real command");Check(breach.Exploration.Structures.ContainsKey(alliedHome.Slot),"combat breakup retains observed building memory");
  var moving=BaseDefenseTests.Load(root);var mobile=moving.World.Units.First(a=>a.Owner==1&&a.Type==0&&VisualCatalog.Visible(a));int oldX=mobile.X,oldY=mobile.Y;moving.Campaign.Alliances[1]=true;moving.UpdateVisibility();int unseen=Enumerable.Range(0,65536).First(c=>(c&255)<moving.World.Width&&(c>>8)<moving.World.Height&&!moving.InSight(c)&&moving.Passable(c&255,c>>8));mobile.X=(unseen&255)*1024;mobile.Y=(unseen>>8)*1024;moving.UpdateVisibility();Check(moving.InSight(unseen),"shared vision follows troop movement");mobile.X=oldX;mobile.Y=oldY;moving.UpdateVisibility();Check(!moving.InSight(unseen)&&moving.Discovered(unseen),"departed allied troop leaves explored memory without live sight");
  var noEnemies=BaseDefenseTests.Load(root,6);Check(!noEnemies.OpponentEnabled&&noEnemies.Opponent.Explored.Count==0,"mission6 remains without AI terrain revelation");File.WriteAllText(output,JsonSerializer.Serialize(new{Checks=checks,Passed=true,Limit="Engine fixtures; UI rendering not manually approved"},new JsonSerializerOptions{WriteIndented=true}));
 }
}
